/*
 * UI icons: Font Awesome 6 Sharp Light (Pro, owner licence; v6.5.1), drawn as
 * inline SVG from the owner's font file so there's no icon-font flash and
 * icons follow currentColor. Names match the lucide icons they replace, so
 * screens import from here unchanged. Generated by scripts/icons-from-font.py;
 * add icons there, not by hand. The design editor keeps lucide for icons inside
 * customer designs.
 */
import { forwardRef, type ForwardRefExoticComponent, type RefAttributes, type SVGProps } from "react";
import { cn } from "@/lib/utils";

export interface IconProps extends SVGProps<SVGSVGElement> {
  size?: number | string;
  /** Accepted for lucide compatibility; Font Awesome glyphs are filled. */
  strokeWidth?: number | string;
  absoluteStrokeWidth?: boolean;
}

export type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>;
/** Kept so existing `type LucideIcon` annotations keep working. */
export type LucideIcon = Icon;

function icon(name: string, viewBox: string, d: string): Icon {
  const C = forwardRef<SVGSVGElement, IconProps>(function FaIcon({ size = 24, strokeWidth: _sw, absoluteStrokeWidth: _asw, className, ...props }, ref) {
    const labelled = props["aria-label"] !== undefined || props["aria-labelledby"] !== undefined;
    return (
      <svg
        ref={ref}
        xmlns="http://www.w3.org/2000/svg"
        viewBox={viewBox}
        width={size}
        height={size}
        fill="currentColor"
        focusable="false"
        aria-hidden={labelled ? undefined : true}
        role={labelled ? "img" : undefined}
        className={cn("fa-icon", className)}
        {...props}
      >
        <path d={d} />
      </svg>
    );
  });
  C.displayName = name;
  return C;
}

